// Кейс: .qa/tests/monitoring/MON-016.md (шаги 3–4) · план: .qa/e2e-app/specs/app.md (1.20)
// Шаг 2: без галочки «כל שטח המים נראה…» «המשך» серая; с галочкой при обычном кадре без подсказок — активна.
// РУЧНОЕ ПРЕДУСЛОВИЕ: второй телефон подключён (#4a869b), громкость на максимуме; телефон неподвижно на подставке,
// задняя камера на освещённую сцену с деталями, линза чистая. Мониторинг НЕ запускается («המשך» не нажимается).
import { by, assert, checkedFromValue } from '../../lib/appium.mjs';
import { openCameraStep, visibleCameraHints, waitEnabled } from '../../lib/banci.mjs';

export const name = 'Шаг 2: без галочки «המשך» серая; галочка «כל שטח המים נראה…» + обычный кадр без подсказок → «המשך» активна #f7bfca @iphone @app @prod-safe';

async function setChecked(el, want) {
  if (checkedFromValue(await el.attr('value')) === want) return;
  await el.click();
  const end = Date.now() + 5000;
  while (Date.now() < end) {
    if (checkedFromValue(await el.attr('value')) === want) return;
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error(`Проверка не прошла: галочка «כל שטח המים נראה…» — ожидалось ${want ? 'checked' : 'unchecked'}, value=«${await el.attr('value')}»`);
}

export default async function (app) {
  const water = await openCameraStep(app);
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на шаге 2' });

  // 1. Без галочки — «המשך» серая (F-15 AC8; MON-005).
  await setChecked(water, false);
  await waitEnabled(next, false, { what: '«המשך» без галочки «כל שטח המים נראה…»' });

  // 2. Галочка + обычный кадр: подсказки уходят (решение по последней секунде, f0e1ea8), «המשך» активна (F-15 AC4, AC8).
  await setChecked(water, true);
  const end = Date.now() + 15000;
  let hints = await visibleCameraHints(app);
  while (hints.length && Date.now() < end) {
    await new Promise((r) => setTimeout(r, 500));
    hints = await visibleCameraHints(app);
  }
  assert(!hints.length, `ПРЕДУСЛОВИЕ/С2: при обычном кадре нет подсказок, а видно: «${hints.join('», «')}» — проверить: телефон неподвижен на подставке, камера на освещённую сцену с деталями, линза чистая; если кадр нормальный — возможна ложная подсказка, проверить вручную (MON-016)`);
  await waitEnabled(next, true, { what: '«המשך» с галочкой при обычном кадре без подсказок' });

  // Выход без запуска мониторинга.
  await app.restart();
}
